{
  "root_causes": [
    {
      "service": "reservation",
      "fault_kind": "pod_unavailable",
      "evidence": [
        {
          "kind": "metric",
          "sql": "SELECT metric, attr_k8s_deployment_name, count(*) n, avg(value) v, min(value) mn, max(value) mx FROM abnormal_metrics WHERE metric = 'k8s.deployment.available' AND attr_k8s_deployment_name = 'reservation' GROUP BY 1,2",
          "claim": "Reservation deployment reports k8s.deployment.available = 0 across all 13 abnormal samples."
        },
        {
          "kind": "metric",
          "sql": "SELECT attr_k8s_pod_name, metric, count(*) n FROM normal_metrics WHERE attr_k8s_deployment_name = 'reservation' AND metric = 'container.cpu.usage' GROUP BY 1,2",
          "claim": "In the normal period reservation runs a live pod, reservation-57d77c7445-tkr7t, with 48 samples of container metrics."
        },
        {
          "kind": "trace",
          "sql": "SELECT service_name, span_name, attr_status_code, count(*) c FROM abnormal_traces WHERE span_name LIKE 'reservation%' OR span_name LIKE '%Reservation/%' GROUP BY 1,2,3",
          "claim": "Abnormal traces contain no spans emitted by the reservation service; only frontend's client-side reservation spans appear, all with Error status."
        },
        {
          "kind": "trace",
          "sql": "SELECT service_name, span_name, attr_status_code, count(*) c, avg(duration)/1e6 ms FROM abnormal_traces WHERE span_name IN ('reservation.Reservation/CheckAvailability','HTTP /hotels') GROUP BY 1,2,3",
          "claim": "Frontend CheckAvailability calls fail in about 0.016 ms, and HTTP /hotels fails 867 times, so the failure is immediate."
        },
        {
          "kind": "log",
          "sql": "SELECT service_name, level, message, count(*) c FROM abnormal_logs WHERE level = 'ERROR' GROUP BY 1,2,3 ORDER BY c DESC",
          "claim": "Frontend logs 768 'Reservation check availability failed' errors; these are the only error logs in the abnormal period."
        }
      ]
    }
  ],
  "propagation": [
    {
      "from": "reservation",
      "to": "frontend",
      "evidence": [
        {
          "kind": "trace",
          "sql": "SELECT service_name, span_name, attr_status_code, count(*) c FROM abnormal_traces WHERE service_name = 'frontend' AND (span_name LIKE '%Reservation%' OR span_name = 'HTTP /hotels') GROUP BY 1,2,3",
          "claim": "Frontend's reservation CheckAvailability calls and its HTTP /hotels requests turn into Error spans, which the user sees."
        }
      ]
    }
  ]
}
